export type KoyalMemory = { id: string; text: string; createdAt: number };
export const MEMORY_STORAGE_KEY: string;
export const MAX_MEMORIES: number;
export const MAX_MEMORY_LENGTH: number;
export const MAX_MEMORY_CONTEXT_LENGTH: number;
export function normalizeMemories(value: unknown): KoyalMemory[];
export function loadMemories(storage: Pick<Storage, "getItem">): KoyalMemory[];
export function saveMemories(storage: Pick<Storage, "setItem">, memories: unknown): boolean;
export function createMemory(text: string, options?: { id?: string; createdAt?: number }): KoyalMemory;
export function addMemory(storage: Pick<Storage, "setItem">, memories: unknown, text: string, options?: { id?: string; createdAt?: number }): KoyalMemory[];
export function deleteMemory(storage: Pick<Storage, "setItem">, memories: unknown, id: string): KoyalMemory[];
export function buildMemoryContext(memories: unknown): string;
